import copy
def is_closed(cells,g):
    # bounding box border must be in comp
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    border={(r,c) for r in range(r0,r1+1) for c in (c0,c1)} | {(r,c) for c in range(c0,c1+1) for r in (r0,r1)}
    return border <= set(cells)

