    H=len(g);W=len(g[0])
    objs=objs(g)
    O=[]
    for col,r0,c0,h,w,sz in objs:
        cells={(r0+i,c0+j) for i in range(h) for j in range(w) if g[r0+i][c0+j]==col}
        closed=is_closed(cells,g)
        O.append(dict(col=col,r0=r0,c0=c0,h=h,w=w,cells=cells,closed=closed))
    out=[[0]*W for _ in range(H)]
    def occ(others,r0,c0,h,w):
        return any((r0+i,c0+j) in o['cells'] for o in others for i in range(h) for j in range(w))
    def blocked(others,delta,r0,c0):
        r1=r0+delta
        if r1<0 or r1+h>H: return True
        for i in range(h):
            for j in range(w):
                rr,cc=r1+i,c0+j
                if (rr,cc) in o['cells']: continue
                if any((rr-i2,cc-j2) in others['cells'] for others in [o] for o in []): pass
        # check against all other objects' cells (including their occupied cells regardless of closeness)
        return any(any((r1+i,c0+j) in od['cells'] for od in others if od is not o) for i in range(h) for j in range(w) if (r1+i,c0+j) in o['cells'])
    # simpler: sliding each object independently until collision with any static other object's cells
    res=[]
    for o in O:
        others=[x for x in O if x is not o]
